import React, { useState } from "react";
import Sidebarmov from "../../components/Sidebarmov";
import HeaderPanel from "../../components/HeaderPanel";
import "../../components/admin.css"; 
import axios from 'axios';

// Importamos useNavigate para cambiar de página
import { useNavigate } from 'react-router-dom';

const API_URL = "http://localhost:3001/api/productos"; 

export default function FormularioEntradaProducto() {

    const navigate = useNavigate(); // Hook para navegación
    const { userId } = useContext(AuthContext);
    // === ESTADOS ===
    const [formData, setFormData] = useState({
        id_producto: '',
        cantidad_m: '',
        observaciones: '',
        id_usuario: userId || 'Adm-01',
    });

    const [productoEncontrado, setProductoEncontrado] = useState(null);
    const [mensaje, setMensaje] = useState({ text: '', type: '' });
    const [cargando, setCargando] = useState(false);

    // Manejar cambios en inputs
    const handleChange = (e) => {
        const { name, value } = e.target;
        setFormData(prev => ({ ...prev, [name]: value }));
    };

    // 1. BUSCAR PRODUCTO AL PRESIONAR ENTER
    const handleCheckProducto = async (e) => {
        if (e.key === 'Enter') {
            e.preventDefault(); 
            const id = formData.id_producto;
            if (!id) return;

            setCargando(true);
            setMensaje({ text: '', type: '' });
            setProductoEncontrado(null);

            try {
                const response = await axios.get(`${API_URL}/check/${id}`);

                if (response.data.found) {
                    setProductoEncontrado(response.data.product);
                    // Feedback visual inmediato
                    setMensaje({ 
                        text: `Producto: ${response.data.product.nom_producto} | Stock Actual: ${response.data.product.stock_actual}`, 
                        type: 'success' 
                    });
                }
            } catch (error) {
                if (error.response && error.response.status === 404) {
                    setMensaje({ text: 'Producto no encontrado. Verifique el ID.', type: 'error' });
                } else {
                    console.error("Error:", error);
                    setMensaje({ text: 'Error al buscar el producto.', type: 'error' });
                }
            } finally {
                setCargando(false);
            }
        }
    };

    // 2. ENVIAR FORMULARIO (SUMAR STOCK)
    const handleSubmit = async (e) => {
        e.preventDefault();

        if (!productoEncontrado) {
            setMensaje({ text: 'Primero valide el producto con ENTER.', type: 'error' });
            return;
        }
        if (!formData.cantidad_m || parseInt(formData.cantidad_m) <= 0) {
            setMensaje({ text: 'La cantidad debe ser mayor a 0.', type: 'error' });
            return;
        }

        setCargando(true);
        setMensaje({ text: '', type: '' });

        const dataToSend = {
            id_usuario: formData.id_usuario,
            cantidad_m: formData.cantidad_m,
            observaciones: formData.observaciones,
            es_nuevo_producto: 'false', 
            id_producto_existente: formData.id_producto,
        };

        try {
            const response = await axios.post(`${API_URL}/inventario`, dataToSend, {
                headers: { 'Content-Type': 'application/json' },
            });

            setMensaje({ text: 'Stock actualizado correctamente. Redirigiendo...', type: 'success' });

            // 3. REDIRECCIÓN AUTOMÁTICA
            // Esperamos 1.5 segundos para que el usuario lea el mensaje y luego vamos a la lista
            setTimeout(() => {
                handleReset();
                // Asegúrate que esta ruta coincida con la ruta de tu archivo Productos.jsx en App.js
                navigate('/productos'); 
            }, 1500);

        } catch (error) {
            console.error("Error:", error);
            setMensaje({ text: 'Error al actualizar el stock.', type: 'error' });
        } finally {
            setCargando(false);
        }
    };

    const handleReset = () => {
        setFormData({
            id_producto: '',
            cantidad_m: '',
            observaciones: '',
            id_usuario: 1,
        });
        setProductoEncontrado(null);
        setMensaje({ text: '', type: '' });
    };

    return (
        <div className="dashboard-layout">
            <Sidebarmov />
            <main className="contenido">
                <HeaderPanel title="Entrada de Stock"/>

                {mensaje.text && (
                    <div className={`alerta ${mensaje.type}`}>
                        {mensaje.text}
                    </div>
                )}

                <section className="cuadro-blanco form-producto">
                    <form className="formulario" onSubmit={handleSubmit}>

                        {/* ID PRODUCTO */}
                        <div className="campo">
                            <label htmlFor="id_producto">ID Producto (Presiona Enter)</label>
                            <input 
                                type="number" 
                                id="id_producto" 
                                name="id_producto" 
                                placeholder="Escribe ID y presiona ENTER" 
                                required 
                                value={formData.id_producto}
                                onChange={handleChange}
                                onKeyDown={handleCheckProducto} // Cambiado a onKeyDown para mejor compatibilidad
                                disabled={cargando}
                            />
                        </div>

                        {/* DATOS DE SOLO LECTURA */}
                        <div className="campo-grupo" style={{ display: 'flex', gap: '10px' }}>
                            <div className="campo" style={{ flex: 2 }}>
                                <label>Producto</label>
                                <input 
                                    type="text" 
                                    readOnly 
                                    value={productoEncontrado ? productoEncontrado.nom_producto : ''}
                                    className={productoEncontrado ? 'valido' : ''}
                                    placeholder="Nombre del producto"
                                />
                            </div>
                            <div className="campo" style={{ flex: 1 }}>
                                <label>Stock Actual</label>
                                <input 
                                    type="number" 
                                    readOnly 
                                    value={productoEncontrado ? productoEncontrado.stock_actual : ''}
                                    style={{ fontWeight: 'bold', color: '#2ecc71' }}
                                    placeholder="0"
                                />
                            </div>
                        </div>

                        {/* CANTIDAD A SUMAR */}
                        <div className="campo">
                            <label htmlFor="cantidad_m">Cantidad a ingresar (+)</label>
                            <input 
                                type="number" 
                                id="cantidad_m" 
                                name="cantidad_m" 
                                placeholder="Ej: 50" 
                                required 
                                min="1"
                                value={formData.cantidad_m}
                                onChange={handleChange}
                                disabled={!productoEncontrado || cargando}
                                style={{ border: '2px solid #3498db' }}
                            />
                        </div>

                        <div className="campo">
                            <label htmlFor="observaciones">Observaciones</label>
                            <textarea 
                                id="observaciones" 
                                name="observaciones" 
                                rows="2"
                                value={formData.observaciones}
                                onChange={handleChange}
                                disabled={!productoEncontrado || cargando}
                            ></textarea>
                        </div>

                        <div className="botones">
                            <button type="submit" className="btn-guardar" disabled={!productoEncontrado || cargando}>
                                <i className="fa-solid fa-plus"></i> {cargando ? 'Procesando...' : 'Sumar al Stock'}
                            </button>
                            <button type="button" className="btn-cancelar" onClick={() => navigate('/productos')} disabled={cargando}>
                                Cancelar
                            </button>
                        </div>
                    </form>
                </section>
            </main>
        </div>
    );
}
